package com.tekwatt.firmware.service;import com.tekwatt.firmware.dto.*;import com.tekwatt.firmware.entity.*;import com.tekwatt.firmware.repository.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;@Service@Transactional public class FirmwareService{private final FirmwarePackageRepository packages;private final FirmwareUpdateJobRepository jobs;public FirmwareService(FirmwarePackageRepository p,FirmwareUpdateJobRepository j){packages=p;jobs=j;}public FirmwarePackage createPackage(FirmwarePackageRequest r){if(packages.existsByVendorIgnoreCaseAndModelIgnoreCaseAndVersion(r.vendor(),r.model(),r.version()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Firmware version already exists");return packages.save(new FirmwarePackage(r.vendor(),r.model(),r.version(),r.downloadUrl(),r.checksum(),r.checksumAlgorithm(),r.signature(),r.fileSizeBytes()));}@Transactional(readOnly=true)public List<FirmwarePackage>packages(){return packages.findAll();}@Transactional(readOnly=true)public FirmwarePackage packageById(UUID id){return packages.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Firmware package not found"));}public FirmwareUpdateJob createJob(CreateUpdateJobRequest r){FirmwarePackage p=packageById(r.firmwarePackageId());if(!p.getActive())throw new ResponseStatusException(HttpStatus.CONFLICT,"Firmware package is inactive");return jobs.save(new FirmwareUpdateJob(r.tenantId(),r.chargerId(),r.firmwarePackageId(),r.ocppVersion(),r.scheduledAt()));}@Transactional(readOnly=true)public FirmwareUpdateJob job(UUID id){return jobs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Update job not found"));}@Transactional(readOnly=true)public List<FirmwareUpdateJob>jobs(UUID tenantId){return jobs.findAllByTenantIdOrderByCreatedAtDesc(tenantId);}public FirmwareUpdateJob status(UUID id,UpdateJobStatusRequest r){FirmwareUpdateJob j=job(id);j.update(r.status(),r.statusInfo());return j;}}
